CREATE TABLE public.channel_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), platform text NOT NULL, external_user_id text NOT NULL, user_id uuid NOT NULL, bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE, conversation_id uuid REFERENCES public.conversations(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(platform,external_user_id));
GRANT SELECT,DELETE ON public.channel_identities TO authenticated; GRANT ALL ON public.channel_identities TO service_role;
ALTER TABLE public.channel_identities ENABLE ROW LEVEL SECURITY;
CREATE POLICY channel_owner_read ON public.channel_identities FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY channel_owner_disconnect ON public.channel_identities FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.channel_pairings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), platform text NOT NULL, user_id uuid NOT NULL, bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.channel_pairings TO service_role; ALTER TABLE public.channel_pairings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.channel_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), platform text NOT NULL, event_id text NOT NULL, identity_id uuid NOT NULL REFERENCES public.channel_identities(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'processing', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(platform,event_id));
GRANT ALL ON public.channel_deliveries TO service_role; ALTER TABLE public.channel_deliveries ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX channel_one_processing ON public.channel_deliveries(identity_id) WHERE status='processing';
CREATE FUNCTION public.channel_touch() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER channel_identity_touch BEFORE UPDATE ON public.channel_identities FOR EACH ROW EXECUTE FUNCTION public.channel_touch();
CREATE TRIGGER channel_pairing_touch BEFORE UPDATE ON public.channel_pairings FOR EACH ROW EXECUTE FUNCTION public.channel_touch();
CREATE TRIGGER channel_delivery_touch BEFORE UPDATE ON public.channel_deliveries FOR EACH ROW EXECUTE FUNCTION public.channel_touch();
CREATE FUNCTION public.consume_channel_pairing(p_platform text,p_external_user text,p_token_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE p public.channel_pairings; existing public.channel_identities; result uuid; BEGIN IF p_platform NOT IN ('telegram','xchat') OR length(p_external_user)>128 THEN RAISE EXCEPTION 'Invalid channel'; END IF; SELECT * INTO p FROM public.channel_pairings WHERE platform=p_platform AND token_hash=p_token_hash AND expires_at>now() FOR UPDATE; IF NOT FOUND THEN RETURN NULL; END IF; IF NOT EXISTS(SELECT 1 FROM public.bots WHERE id=p.bot_id AND owner_id=p.user_id) THEN RETURN NULL; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_platform||':'||p_external_user)); SELECT * INTO existing FROM public.channel_identities WHERE platform=p_platform AND external_user_id=p_external_user FOR UPDATE; IF FOUND AND existing.user_id<>p.user_id THEN RETURN NULL; END IF; IF existing.id IS NOT NULL THEN UPDATE public.channel_identities SET bot_id=p.bot_id,conversation_id=CASE WHEN bot_id=p.bot_id THEN conversation_id ELSE NULL END WHERE id=existing.id RETURNING id INTO result; ELSE INSERT INTO public.channel_identities(platform,external_user_id,user_id,bot_id) VALUES(p_platform,p_external_user,p.user_id,p.bot_id) RETURNING id INTO result; END IF; DELETE FROM public.channel_pairings WHERE id=p.id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.consume_channel_pairing(text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_channel_pairing(text,text,text) TO service_role;
CREATE FUNCTION public.store_channel_credential(p_name text,p_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE sid uuid; BEGIN IF p_name NOT IN ('CEYO_TELEGRAM_CHANNEL_TOKEN','CEYO_XCHAT_TOKEN','CEYO_XCHAT_PIN','CEYO_XCHAT_USER_ID','CEYO_XCHAT_KEY_VERSION','CEYO_XCHAT_FINGERPRINT','CEYO_XCHAT_CONSUMER_SECRET') OR p_value IS NULL OR length(p_value)=0 THEN RAISE EXCEPTION 'Invalid credential'; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_name)); SELECT id INTO sid FROM vault.secrets WHERE name=p_name LIMIT 1; IF sid IS NULL THEN PERFORM vault.create_secret(p_value,p_name,'Official messaging channel'); ELSE PERFORM vault.update_secret(sid,p_value,p_name,'Official messaging channel'); END IF; END $$;
REVOKE ALL ON FUNCTION public.store_channel_credential(text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.store_channel_credential(text,text) TO service_role;
CREATE FUNCTION public.read_channel_credential(p_name text) RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name=p_name AND p_name IN ('CEYO_TELEGRAM_CHANNEL_TOKEN','CEYO_XCHAT_TOKEN','CEYO_XCHAT_PIN','CEYO_XCHAT_USER_ID','CEYO_XCHAT_KEY_VERSION','CEYO_XCHAT_FINGERPRINT','CEYO_XCHAT_CONSUMER_SECRET') LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.read_channel_credential(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.read_channel_credential(text) TO service_role;